
.card {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  background: linear-gradient(180deg, var(--c-surface), var(--c-surface-2));
  border: 1px solid var(--c-border);
  border-radius: 16px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 12px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.5);
}

.header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--c-border);
}

.title-wrap {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.title {
  font-size: 20px;
  font-weight: 700;
  color: var(--c-accent);
  letter-spacing: 6px;
}

.subtitle {
  font-size: 11px;
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.mood {
  font-size: 12px;
  color: var(--c-accent);
  background: rgba(212, 93, 121, 0.16);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  padding: 5px 14px;
}

.body {
  padding: 14px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.arc {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  background: rgba(255, 158, 181, 0.08);
  border: 1px solid rgba(212, 93, 121, 0.35);
  border-radius: 10px;
  padding: 10px 14px;
}

.arc-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--c-primary);
  letter-spacing: 1px;
}

.arc-hint {
  font-size: 11px;
  color: var(--c-text-muted);
}

.divider {
  height: 1px;
  background: var(--c-border);
  opacity: 0.5;
}

.bar-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bar-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.bar-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  letter-spacing: 1px;
}

.bar-pct {
  font-size: 11px;
  font-weight: 700;
  color: var(--c-text-muted);
}

.track {
  height: 10px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.3);
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.fill-primary {
  background: linear-gradient(90deg, #7c2d3e, var(--c-primary));
}

.fill-danger {
  background: linear-gradient(90deg, #8c2a3e, var(--c-danger));
}

.fill-accent {
  background: linear-gradient(90deg, #8c4760, var(--c-accent));
}

.bar-note {
  font-size: 11px;
  color: var(--c-text-muted);
}
